<script setup lang="ts">
import { ref, computed } from 'vue'; import type { Person, Entity, Interaction, PersonReflection, FollowUp, ContactMethod, PersonFact } from '@zhijiao/shared'; import { entities, directory, selfPersonId } from '../state'; import { label, dateLabel, sortedInteractions } from '../format';
import Avatar from './Avatar.vue'; import Icon from './Icon.vue'; import RecordCard from './RecordCard.vue';
const props = defineProps<{ person: Person }>(); const emit = defineEmits<{ back: []; edit: [record: Entity]; add: [kind: 'contact' | 'fact' | 'reflection' | 'followUp', personId: string]; journal: [personId: string]; avatar: [personId: string]; archive: [person: Person]; remove: [person: Person]; history: [record: Entity]; open: [record: Entity]; complete: [record: Entity] }>(); const tab = ref('overview');
const isSelf = computed(() => props.person.id === selfPersonId.value);
const events = computed<Interaction[]>(() => sortedInteractions(entities.value).filter(event => event.participantIds.includes(props.person.id)));
const reflections = computed(() => entities.value.filter((record): record is PersonReflection => record.kind === 'reflection' && record.personId === props.person.id));
const tasks = computed(() => entities.value.filter((record): record is FollowUp => record.kind === 'followUp' && record.personIds.includes(props.person.id)));
const contacts = computed(() => entities.value.filter((record): record is ContactMethod => record.kind === 'contact' && record.personId === props.person.id));
const facts = computed(() => entities.value.filter((record): record is PersonFact => record.kind === 'fact' && record.personId === props.person.id));
const tags = computed(() => entities.value.filter(record => record.kind === 'personTag' && record.personId === props.person.id).map(edge => entities.value.find(record => record.kind === 'tag' && record.id === ('tagId' in edge ? edge.tagId : ''))).filter((record): record is Extract<Entity, {kind:'tag'}> => record?.kind === 'tag'));
const visibleRecords = computed<Entity[]>(() => tab.value === 'interactions' ? events.value : tab.value === 'reflections' ? reflections.value : tasks.value);
</script>
<template><div class="person-detail"><button class="text-button back-button" @click="emit('back')"><Icon name="back" :size="17" />返回人物</button><section class="profile-header"><button class="avatar-edit" aria-label="编辑头像" @click="emit('avatar', person.id)"><Avatar :name="person.displayName" :avatar="person.avatar" large /><span class="avatar-edit-badge"><Icon name="edit" :size="13" /></span></button><div class="profile-intro"><p class="eyebrow">{{ isSelf ? '账号本人' : label(person.status) }}</p><h1>{{ person.displayName }}</h1><p v-if="person.summary">{{ person.summary }}</p><p v-if="person.aliases?.length" class="muted">也称 {{ person.aliases.join('、') }}</p></div><div class="profile-actions"><button class="button primary" @click="emit('journal', person.id)"><Icon name="plus" :size="17" />记一笔</button><button class="button secondary" @click="emit('edit', person)">编辑资料</button></div></section><nav class="detail-tabs" aria-label="人物详情分类"><button v-for="item in [{id:'overview',name:'概览'}, {id:'interactions',name:'交往',count:events.length}, {id:'reflections',name:'感受与印象',count:reflections.length}, {id:'tasks',name:'事项',count:tasks.length}]" :key="item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.name }} <small v-if="item.count">{{ item.count }}</small></button></nav><div v-if="tab === 'overview'" class="detail-grid"><div><section class="panel"><div class="section-title"><h2>基本资料</h2><button class="text-button" @click="emit('history', person)"><Icon name="history" :size="16" />历史</button></div><dl class="definition-list"><template v-if="person.fullName"><dt>正式姓名</dt><dd>{{ person.fullName }}</dd></template><template v-if="person.metContext"><dt>如何相识</dt><dd>{{ person.metContext }}</dd></template><template v-if="person.metOn"><dt>相识时间</dt><dd>{{ dateLabel(person.metOn) }}</dd></template><template v-if="person.birthday"><dt>生日</dt><dd>{{ dateLabel(person.birthday) }}</dd></template><template v-if="events.length"><dt>最近交往</dt><dd>{{ dateLabel(events[0].occurredAt || events[0].occurredOn) }} · {{ events[0].title }}</dd></template><template v-if="person.notes"><dt>备注</dt><dd class="preserve">{{ person.notes }}</dd></template></dl><p v-if="!person.fullName && !person.metContext && !person.birthday && !person.notes && !events.length" class="muted">按已知程度慢慢补充，不必一次填完。</p><div v-if="tags.length" class="tag-options"><span v-for="tag in tags" :key="tag.id" class="chip">{{ tag.name }}</span></div></section><section class="panel"><div class="section-title"><h2>事实与偏好</h2><button class="text-button" @click="emit('add', 'fact', person.id)"><Icon name="plus" :size="16" />补充</button></div><RecordCard v-for="record in facts" :key="record.id" :record="record" :people="directory" @open="emit('open', $event)" @edit="emit('edit', $event)" /><p v-if="!facts.length" class="muted">记录本人陈述、观察或转述，并保留来源。</p></section></div><div><section class="panel"><div class="section-title"><h2>联系方式</h2><button class="text-button" @click="emit('add', 'contact', person.id)"><Icon name="plus" :size="16" />添加</button></div><RecordCard v-for="record in contacts" :key="record.id" :record="record" :people="directory" @open="emit('open', $event)" @edit="emit('edit', $event)" /><p v-if="!contacts.length" class="muted">还没有联系方式。</p></section><section class="panel"><div class="section-title"><h2>待办事项</h2><button class="text-button" @click="emit('add', 'followUp', person.id)">添加</button></div><RecordCard v-for="record in tasks.filter(task => task.status === 'pending')" :key="record.id" :record="record" :people="directory" @open="emit('open', $event)" @edit="emit('edit', $event)" @complete="emit('complete', $event)" /><p v-if="!tasks.some(task => task.status === 'pending')" class="muted">没有未完成的事项。</p></section><section v-if="!isSelf" class="quiet-actions"><button class="text-button" @click="emit('archive', person)">{{ person.status === 'archived' ? '恢复来往' : '归档人物' }}</button><button class="text-button danger" @click="emit('remove', person)">删除人物</button></section></div></div><div v-else><div class="section-title section-toolbar"><p class="muted">{{ tab === 'interactions' ? '共同经历按发生日期排列' : tab === 'reflections' ? '个人的想法，保留依据与不同解释' : '约定和计划，逾期从期限派生' }}</p><button class="button secondary" @click="tab === 'interactions' ? emit('journal', person.id) : emit('add', tab === 'reflections' ? 'reflection' : 'followUp', person.id)"><Icon name="plus" :size="16" />{{ tab === 'interactions' ? '记一笔' : '添加' }}</button></div><div class="record-list"><RecordCard v-for="record in visibleRecords" :key="record.id" :record="record" :people="directory" @open="emit('open', $event)" @edit="emit('edit', $event)" @complete="emit('complete', $event)" /></div><div v-if="!visibleRecords.length" class="empty"><Icon :name="tab === 'interactions' ? 'journal' : tab === 'tasks' ? 'tasks' : 'leaf'" :size="36" /><h3>还没有记录</h3><p>从一次相处开始，慢慢记下值得保留的细节。</p></div></div></div></template>
